async function main(){
  const root = figma.root;
  let ws = root.children.find(p=>p.name==='03 · Workspace');
  if(!ws){ ws = figma.createPage(); ws.name='03 · Workspace'; await figma.setCurrentPageAsync(ws);}else{ await figma.setCurrentPageAsync(ws); }
  const page = ws;

  // Load fonts
  const styles=[['Regular','Regular'],['Medium','Medium'],['Semi Bold','Semi Bold'],['Bold','Bold'],['Extra Bold','Extra Bold']];
  for(const s of styles){ try{ await figma.loadFontAsync({family:'Inter', style:s[1]});}catch(e){} }

  // colors
  const C={blue:{r:0,g:0.478,b:1}, ink:{r:0.1,g:0.1,b:0.1216}, sub:{r:0.42,g:0.45,b:0.5}, bg:{r:0.961,g:0.969,b:0.976}, white:{r:1,g:1,b:1}, line:{r:0.9,g:0.91,b:0.93}, green:{r:0.11,g:0.698,b:0.42}, neg:{r:0.1,g:0.1,b:0.12}, card2:{r:1,g:0.91,b:0.88} };
  const c=(o)=> ({r:o.r,g:o.g,b:o.b});

  function frame(name,x,y,w,h){ const f=figma.createFrame(); f.name=name; f.x=x; f.y=y; f.resize(w,h); if(w>0&&h>0){f.clipsContent=true;} page.appendChild(f); return f; }
  function rect(parent,x,y,w,h,fill){ const r=figma.createRectangle(); r.x=x; r.y=y; r.resize(w,h); r.fills=[{type:'SOLID',color:c(fill)}]; parent.appendChild(r); return r; }
  function text(parent,str,x,y,size,style,fill,aln){
    const t=figma.createText(); t.fontName={family:'Inter',style:style}; t.fontSize=size; t.characters=str; t.x=x; t.y=y;
    if(aln==='center'){t.textAlignHorizontal='CENTER';}
    t.fills=[{type:'SOLID',color:c(fill)}]; parent.appendChild(t); return t;
  }
  function place(compId,parent,x,y){
    const nd=figma.getNodeById(compId); let inst;
    try{ inst = nd.type==='COMPONENT' ? nd.createInstance() : nd.clone(); }catch(e){ inst=nd.clone(); }
    parent.appendChild(inst); inst.x=x; inst.y=y; return inst;
  }
  function stroke(rectNode,w,color){ rectNode.strokeWeight=w; rectNode.strokes=[{type:'SOLID',color:c(color)}]; }
  function setTextLabel(inst,label){ const t=inst.findOne(n=>n.type==='TEXT'); if(t){ try{ t.characters=label; }catch(e){} } }

  // ============ 01_Get_Started ============
  const s1 = frame('01_Get_Started',0,0,375,812);
  const bg = rect(s1,0,0,375,812,C.bg);
  place('1:33', s1, 0,0); // status bar
  // logo
  const logo = place('6:10', s1, 97, 96);
  // illustration
  const ill = place('5:6', s1, 67.5, 190); // 240 wide
  // headline
  text(s1,'Going cashless has never been easier with the world\u2019s leading expense manager.',30,520,17,'Regular',{r:0.42,g:0.45,b:0.5},'center');
  // We'll set width using text auto? set textResize. Set a wrapping width.
  const headText = s1.children.find(n=>n.name===''); // mark
  // Build main heading instead
  const subT = text(s1,'Simple, secure and smart.',30,486,24,'Bold',C.ink,'center');
  // Get Started button
  const btn = place('1:23', s1, 16, 660);
  if(btn){ try{ btn.resize(343,56); }catch(e){} setTextLabel(btn,'Get Started'); }

  // ============ 02_Home ============
  const s2 = frame('02_Home',455,0,375,812);
  rect(s2,0,0,375,812,C.bg);
  place('1:33', s2, 0,0);
  // Header: greeting + avatar + minus plus
  text(s2,'Home',20,64,16,'Medium',C.sub);
  text(s2,'Hello, Maria',20,88,24,'Extra Bold',C.ink);
  const ava = place('5:4', s2, 287, 68); // avatar
  // avatar recolor handled by component; place plus? keep top-left
  // Balance card
  const bc=frame('balance',20,140,335,170); bc.fills=[{type:'SOLID',color:c(C.blue)}]; bc.cornerRadius=24;
  const bcGrad = rect(bc,0,0,335,170,C.blue);
  // put gradient: use two stacked translucent rects
  text(bc,'My Balance',20,24,13,'Medium',C.white);
  text(bc,'$25,520.00',20,50,32,'Extra Bold',C.white);
  text(bc,'open balance',20,120,15,'Semi Bold',C.white);
  place('6:4', bc, 120,117); // chevron
  // plus button on balance? new payment via plus
  // Expenses card
  const ec=frame('expenses',20,330,335,210); ec.fills=[{type:'SOLID',color:c(C.white)}]; ec.cornerRadius=24;
  ec.strokes=[{type:'SOLID',color:c(C.line)}]; ec.strokeWeight=1;
  text(ec,'Expenses',20,20,16,'Semi Bold',C.ink);
  // chart area
  const months=['MAR','APR','MAY','JUN','JUL','AUG'];
  const vals=[40,66,50,80,58,46];
  const yBase=160, x0=30, xStep=52, maxH=90;
  for(let i=0;i<6;i++){
    const h=Math.round(vals[i]/100*maxH);
    const x=x0+i*xStep, y=yBase-h;
    const rr=rect(ec,x,y,26,h, i===3?C.blue:{r:0.82,g:0.87,b:0.95});
    rr.cornerRadius=6;
    text(ec,months[i],x,yBase+6,10,'Medium', i===3?C.blue:C.sub);
  }
  // highlight JUN label
  text(ec,'$80.40',x0+3*52+2,yBase-112,12,'Bold',C.blue);
  // Transactions header
  text(s2,'Wallet',20,560,20,'Bold',C.ink);
  const sa=text(s2,'See all',290,564,14,'Semi Bold',C.blue);

  // Transaction rows
  function tx(y,name,date,amt,merchId,rpos){
    const row=frame('tx',20,y,335,72); row.fills=[{type:'SOLID',color:c(C.white)}]; row.cornerRadius=16; row.strokes=[{type:'SOLID',color:c(C.line)}]; row.strokeWeight=1;
    const mc=frame('mc',14,14,44,44); mc.fills=[{type:'SOLID',color:c({r:0.95,g:0.95,b:0.97})}]; mc.cornerRadius=12;
    try{ const m=place(merchId,mc,4,4); try{m.resize(36,36);}catch(e){} }catch(e){}
    text(row,name,70,12,15,'Semi Bold',C.ink);
    text(row,date,70,34,12,'Regular',C.sub);
    text(row,amt,300-40,18,15,'Bold',{r:0.1,g:0.1,b:0.12});
  }
  tx(596,'Nike Air Max 2090','15 Aug 2020','\u2212$243.00','5:9');
  tx(680,'iPad Pro 2020','10 Aug 2020','\u2212$799.00','5:5');
  tx(764,'Uber','5 Mar 2020','+$50.00','5:7');
  // New payment FAB
  const fab=frame('newPayment',299,690,56,56); fab.fills=[{type:'SOLID',color:c(C.blue)}]; fab.cornerRadius=28;
  text(fab,'+',0,6,34,'Regular',C.white);
  fab.findChildren ? null: null;
