async function main(){
  const ws = figma.root.children.find(p=>p.name==='03 · Workspace');
  const lines=[];
  function desc(n,d){
    let t = n.type + ' | ' + n.name;
    if(n.type==='TEXT'){ t += ' | chars="'+(n.characters||'').slice(0,40)+'"'; }
    lines.push('  '.repeat(d)+t);
    if(n.type==='TEXT') return;
    if('children' in n){ for(const c of n.children){ desc(c,d+1);} }
  }
  for(const c of ws.children){ desc(c,0); }
  console.log(lines.join('\n'));
  // write to a text node on canvas so we can screenshot it
  await figma.setCurrentPageAsync(ws);
  const txt = figma.createText(); txt.fontSize=10;
