async function main(){
  const ws = figma.root.children.find(p=>p.name==='03 · Workspace');
  await figma.setCurrentPageAsync(ws);
  // remove old dump
  const old = ws.children.find(c=>c.name==='__DUMP__');
  if(old) old.remove();
  const lines=[];
  for(const name of ['01_Get_Started','02_Home']){
    const f = ws.children.find(c=>c.name===name);
    if(!f){ lines.push(name+': NOT FOUND'); continue; }
    lines.push(name+' id='+f.id+' children='+f.children.length);
    function walk(n,d){
      if(d>2) return;
      lines.push('  '.repeat(d)+n.type+' '+n.name+' x='+Math.round(n.x)+' y='+Math.round(n.y)+' w='+Math.round(n.width)+' h='+Math.round(n.height));
      if(n.type==='TEXT'){ lines.push('  '.repeat(d+1)+'txt="'+n.characters.slice(0,30)+'"'); }
      if('children' in n){ for(const c of n.children) walk(c,d+1); }
    }
    for(const c of f.children) walk(c,1);
  }
  const t=figma.createText(); t.fontSize=9;
  await figma.loadFontAsync({family:'Inter',style:'Regular'});
  t.characters=lines.join('\n'); t.x=1600; t.y=0; t.resize(760,1200);
  ws.appendChild(t); t.name='__DUMP__';
  figma.notify('ok');
}
main().catch(e=>{ figma.notify('ERR '+e.message); });

